"""Identidade visual pessoal do ZasaBoard; referência em docs/design-zasaboard.md."""
import base64
from core.ambiente import PASTA_PERFIS
ICONE = ''

PNG = ''

def aplicar(janela,ctk):
    tema=ctk.ThemeManager.theme
    for classe in ('CTkButton','CTkSlider','CTkProgressBar','CTkSwitch','CTkCheckBox','CTkSegmentedButton'):
        for chave in ('fg_color','progress_color','button_color','selected_color'):
            if chave in tema.get(classe,{}):tema[classe][chave]=['#b94722','#b94722']
        for chave in ('hover_color','button_hover_color','selected_hover_color'):
            if chave in tema.get(classe,{}):tema[classe][chave]=['#d65b2c','#d65b2c']
    pasta=PASTA_PERFIS/'.marca';pasta.mkdir(parents=True,exist_ok=True)
    caminho=pasta/'zasaboard.ico';caminho.write_bytes(base64.b64decode(ICONE))
    janela.after(250,lambda:janela.iconbitmap(str(caminho)) if janela.winfo_exists() else None)
